// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.lwjgl.util.lmdb.LMDB.MDB_MAP_FULL;

import java.io.File;
import java.io.IOException;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * A NONE import into an empty store assigns new dictionary IDs from the fresh value session, without dictionary
 * lookups, while still committing GH-6070's bounded native chunks.
 */
class LmdbInitialNoneFreshImportTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI PREDICATE = VF.createIRI("http://example.com/fresh-none/predicate");
	private static final IRI SHARED = VF.createIRI("http://example.com/fresh-none/shared");

	@TempDir
	File directory;

	@Test
	@Timeout(60)
	void noneImportIntoAnEmptyStoreUsesTheFreshValueSessionAcrossCheckpoints() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			long checkpoints = backing.noneIngestionMetrics().checkpoints();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 0, 500);
				writer.flush();
				assertThat(backing.hasActiveFreshValueSession())
						.as("an initial NONE import resolves new values through the fresh session")
						.isTrue();
				addSubjects(writer, 500, 1000);
				writer.flush();
				assertThat(backing.noneIngestionMetrics().checkpoints())
						.as("NONE still publishes bounded native chunks")
						.isGreaterThanOrEqualTo(checkpoints + 2);
				assertThat(backing.hasActiveFreshValueSession()).isTrue();
				writer.commit();
			}
			assertThat(backing.hasActiveFreshValueSession()).as("the session ends with the NONE attempt").isFalse();
			assertImported(sail, 1000);
		} finally {
			sail.shutDown();
		}
		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try {
			assertImported(reopened, 1000);
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void removalEndsTheFreshSessionWithoutDuplicatingEarlierValues() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 0, 200);
				writer.flush();
				assertThat(backing.hasActiveFreshValueSession()).isTrue();
				writer.removeStatements(subject(0), PREDICATE, SHARED);
				writer.flush();
				assertThat(backing.hasActiveFreshValueSession())
						.as("a removal can retire values the session still maps")
						.isFalse();
				// Values assigned by the session before the removal must resolve to their existing IDs.
				writer.addStatement(subject(1), PREDICATE, VF.createLiteral("again"));
				writer.addStatement(subject(0), PREDICATE, SHARED);
				writer.commit();
			}
			try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
				assertThat(reader.size()).isEqualTo(401);
				// A duplicated subject ID would split these three statements between two IDs.
				try (var statements = reader.getStatements(subject(1), PREDICATE, null, false)) {
					assertThat(statements.stream().count()).isEqualTo(3);
				}
				try (var statements = reader.getStatements(null, PREDICATE, SHARED, false)) {
					assertThat(statements.stream().count()).isEqualTo(200);
				}
			}
		} finally {
			sail.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void capacityReplayOfAFreshChunkReassignsItsRolledBackValues() throws Exception {
		FailingFreshStore sail = new FailingFreshStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 0, 100);
				writer.flush();
				sail.values.mapFullsRemaining = 1;
				addSubjects(writer, 100, 300);
				writer.flush();
				assertThat(sail.values.mapFullsInjected).as("the second chunk must hit the injected MAP_FULL")
						.isEqualTo(1);
				assertThat(backing.hasActiveFreshValueSession())
						.as("capacity replay rolls back provisional IDs and keeps the session")
						.isTrue();
				writer.commit();
			}
			assertImported(sail, 300);
		} finally {
			sail.shutDown();
		}
		LmdbStore reopened = new LmdbStore(directory, config());
		reopened.init();
		try {
			assertImported(reopened, 300);
		} finally {
			reopened.shutDown();
		}
	}

	@Test
	@Timeout(60)
	void noneImportIntoANonEmptyStoreKeepsDictionaryLookups() throws Exception {
		LmdbStore sail = new LmdbStore(directory, config());
		sail.init();
		try {
			LmdbSailStore backing = sail.getBackingStore();
			try (LmdbStoreConnection seed = (LmdbStoreConnection) sail.getConnection()) {
				seed.begin(IsolationLevels.READ_COMMITTED);
				addSubjects(seed, 0, 1);
				seed.commit();
			}
			try (LmdbStoreConnection writer = (LmdbStoreConnection) sail.getConnection()) {
				writer.begin(IsolationLevels.NONE);
				addSubjects(writer, 1, 200);
				writer.flush();
				assertThat(backing.hasActiveFreshValueSession()).isFalse();
				writer.commit();
			}
			assertImported(sail, 200);
		} finally {
			sail.shutDown();
		}
	}

	private static void addSubjects(LmdbStoreConnection writer, int from, int to) {
		for (int i = from; i < to; i++) {
			writer.addStatement(subject(i), PREDICATE, SHARED);
			writer.addStatement(subject(i), PREDICATE, VF.createLiteral("value " + i));
		}
	}

	private static IRI subject(int i) {
		return VF.createIRI("http://example.com/fresh-none/subject/" + i);
	}

	private static void assertImported(LmdbStore sail, int subjects) {
		try (LmdbStoreConnection reader = (LmdbStoreConnection) sail.getConnection()) {
			assertThat(reader.size()).isEqualTo(2L * subjects);
			try (var statements = reader.getStatements(null, PREDICATE, SHARED, false)) {
				assertThat(statements.stream().count()).isEqualTo(subjects);
			}
			for (int i : new int[] { 0, subjects / 2, subjects - 1 }) {
				try (var statements = reader.getStatements(subject(i), PREDICATE, null, false)) {
					assertThat(statements.stream().count()).isEqualTo(2);
				}
			}
		}
	}

	private static final class FailingFreshStore extends LmdbStore {
		private FailingFreshValueStore values;

		private FailingFreshStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException {
			return new LmdbSailStore(directory, properties, config, sketchEnabled,
					(valueDir, storeProperties, settings) -> {
						values = new FailingFreshValueStore(valueDir, storeProperties, settings);
						return values;
					}, TripleStore::new);
		}
	}

	private static final class FailingFreshValueStore extends ValueStore {
		private volatile int mapFullsRemaining;
		private volatile int mapFullsInjected;

		private FailingFreshValueStore(File directory, StoreProperties properties, LmdbStoreConfig config)
				throws IOException {
			super(directory, properties, config);
		}

		@Override
		void persistPreparedValues(PreparedValueBatch prepared) throws IOException {
			if (mapFullsRemaining > 0) {
				mapFullsRemaining--;
				mapFullsInjected++;
				LmdbUtil.E(MDB_MAP_FULL);
			}
			super.persistPreparedValues(prepared);
		}
	}

	private static LmdbStoreConfig config() {
		return new LmdbStoreConfig("spoc,posc").setDirectAdjacencyEnabled(false)
				.setValueOverlayEnabled(false)
				.setInlineLiterals(false)
				.setBulkOperationSize(64);
	}
}
